                                                                                       'reversed_relative_difference '
                                                                                       ':\n'
                                                                                       '    '
                                                                                       '((584/10-706/10)/(706/10) '
                                                                                       ': ℚ) = -61/353 ∧\n'
                                                                                       '    '
                                                                                       '((584/10-706/10)/(706/10) '
